#include "feedback.hpp"
#include "image_observer.hpp"
#include "workspace.hpp"
#include <windows.h>
#include <iostream>
using namespace semes;
static void persist(const fs::path& path,const Json& j){fs::create_directories(fs::absolute(path).parent_path());auto pending=path;pending+=L".pending";if(fs::exists(pending))throw std::runtime_error("Pending feedback session exists");write(pending,j.dump());if(!MoveFileExW(pending.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Session replacement failed");}
int wmain(int argc,wchar_t** wide){Utf8Arguments args(argc,wide);auto argv=args.data();try{
    if(argc<3)throw std::runtime_error("feedback_image_session start new-state image calibration.json policy | observe state image acknowledged-dy acknowledged-dt");std::string operation=argv[1];auto path=fs::u8path(argv[2]);auto root=workspace_root();ImageObserver extractor(root/"data/raw/hw/bmp/20261014/center.bmp",root/"data/reference/joint_center_630_20261022/assets/reference.npz",root/"data/reference/codex_experiments_20261014/joint_yt_visual_feedback_20261023/lines/protocol.json");historical::FeedbackController c;Json state;
    if(operation=="start"){
        if(argc!=6||fs::exists(path))throw std::runtime_error("Choose a new state and provide image, calibration and policy");auto cal=Json::parse(read(fs::u8path(argv[4])));auto observation=extractor.extract(bytes(fs::u8path(argv[3])),cal.at("condition").str());if(!observation.at("success").number)throw std::runtime_error("Initial image measurement failed");cv::Mat projected=matrix(observation.at("X"))*matrix(cal.at("projection")),visual=projected.t();c=historical::FeedbackController(matrix(cal.at("jacobian")),argv[5]);c.start(visual,cv::Mat::zeros(visual.size(),CV_64F));state=Json::dict();state["condition"]=cal.at("condition");state["projection"]=cal.at("projection");state["observations"]=Json::list();state["observations"].push(observation.at("image_sha256"));state["calibration_sha256"]=sha256(fs::u8path(argv[4]));
    }else if(operation=="observe"){
        if(argc!=6)throw std::runtime_error("Provide state, image and two acknowledged increments");state=Json::parse(read(path));c=historical::FeedbackController::from_state(state.at("controller"));auto observation=extractor.extract(bytes(fs::u8path(argv[3])),state.at("condition").str());cv::Mat visual;if(observation.at("success").number){cv::Mat projected=matrix(observation.at("X"))*matrix(state.at("projection"));visual=projected.t();}else visual=cv::Mat(c.s.size(),CV_64F,cv::Scalar(std::numeric_limits<double>::quiet_NaN()));auto parse=[](const char* s){size_t used=0;std::string text=s;double n=std::stod(text,&used);if(used!=text.size()||!std::isfinite(n))throw std::runtime_error("Finite acknowledged increment required");return n;};c.observe(visual,{parse(argv[4]),parse(argv[5])});state["observations"].push(observation.at("image_sha256"));
    }else throw std::runtime_error("Unknown feedback session operation");
    auto action=c.next_action();state["controller"]=c.state();persist(path,state);Json result=Json::dict();result["status"]=c.status;result["turns"]=c.turn;result["maximum_turns"]=20;result["condition"]=state.at("condition");result["feature_rms"]=c.feature_rms;result["suggested_relative_command"]=Json();if(action){Json a=Json::list();a.push((*action)[0]);a.push((*action)[1]);result["suggested_relative_command"]=a;}result["hardware_command_sent"]=false;result["notice"]="Historical simulation limits; suggestions only. Numeric command units are not verified physical robot limits. Visual stop is not independent pose verification.";std::cout<<result.dump()<<'\n';return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
